":"nha_sach","phone":null,"place":"ChIJYbwd04gudTERnXAjtQVOdhY","source":"https://www.google.com/maps/search/?api=1&query=Nh%C3%A0%20s%C3%A1ch%20Nguy%E1%BB%85n%20V%C4%83n%20C%E1%BB%AB%20-%20C%C3%A2y%20G%C3%B5%20805%20H%E1%BB%93ng%20B%C3%A0ng%20TP%20H%E1%BB%93%20Ch%C3%AD%20Minh&query_place_id=ChIJYbwd04gudTERnXAjtQVOdhY","maps":"https://www.google.com/maps/search/?api=1&query=Nh%C3%A0%20s%C3%A1ch%20Nguy%E1%BB%85n%20V%C4%83n%20C%E1%BB%AB%20-%20C%C3%A2y%20G%C3%B5%20805%20H%E1%BB%93ng%20B%C3%A0ng%20TP%20H%E1%BB%93%20Ch%C3%AD%20Minh&query_place_id=ChIJYbwd04gudTERnXAjtQVOdhY","key":"gmaps:ChIJYbwd04gudTERnXAjtQVOdhY","address_new":"805 Hồng Bàng, phường Bình Tây, TP. Hồ Chí Minh","address_old":"805 Hồng Bàng, Quận 6 cũ, TP.HCM cũ"}]'::jsonb) AS s(name text,street text,ward text,district text,category text,phone text,place text,source text,maps text,key text,address_new text,address_old text) WHERE s.category IN ('nha_sach','van_phong_pham') AND s.source LIKE 'https://%' AND (s.place IS NULL OR s.place~'^ChIJ[A-Za-z0-9_-]{20,}$') AND s.address_new LIKE '% '||s.ward||', TP. Hồ Chí Minh' AND (s.phone IS NULL OR s.phone~'^[0-9]{8,11}$')
