AND NOT EXISTS (SELECT 1 FROM public.customers c WHERE lower(btrim(c.address_line))=lower(btrim(s.address_new)) OR (c.province='TP Hồ Chí Minh' AND lower(btrim(c.name))=lower(btrim(s.name))) OR (s.phone IS NOT NULL AND regexp_replace(coalesce(c.phone,''),'[^0-9]','','g')=s.phone))), inserted AS (
